import java.math.BigInteger;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int h = scanner.nextInt();
        scanner.close();

        BigInteger[][] dp = new BigInteger[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j] = BigInteger.ZERO;
            }
        }

        // Initialize dp[0][j] = 1 for all j
        for (int j = 0; j <= n; j++) {
            dp[0][j] = BigInteger.ONE;
        }

        // DP computation
        for (int i = 0; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                for (int k = 0; k < i; k++) {
                    dp[i][j] = dp[i][j].add(
                        dp[k][j - 1].multiply(dp[i - 1 - k][j - 1])
                    );
                }
            }
        }

        BigInteger result = dp[n][n];
        if (h > 0) {
            result = result.subtract(dp[n][h - 1]);
        }
        System.out.println(result);
    }
}
